@push('styles')<style>
.request-stepper{display:grid;grid-template-columns:repeat(4,1fr);gap:.75rem}.request-step{border:0;background:#fff;border-radius:1rem;padding:1rem;box-shadow:0 .35rem 1rem #0c2d5a14;color:#64748b}.request-step span{display:grid;place-items:center;width:2rem;height:2rem;margin:auto;border-radius:50%;background:#e8eef8;font-weight:800}.request-step small{display:block;margin-top:.4rem}.request-step.active{color:#0b5ed7;box-shadow:0 0 0 2px #0b5ed7}.request-step.active span{background:#0b5ed7;color:#fff}.service-choice-card{display:block;position:relative;border:1px solid #dce5f2;border-radius:1rem;padding:1.25rem;background:#fff;cursor:pointer}.service-choice-input{position:absolute;opacity:0}.service-choice-card:has(input:checked){border:2px solid #0b5ed7;background:#f4f8ff}.service-choice-card>strong,.service-choice-card>small{display:block}.service-choice-card>small{color:#64748b}.service-choice-card dl{margin:1rem 0 0}.service-choice-card dl div,.fee-summary-card>div{display:flex;justify-content:space-between;gap:1rem;padding:.35rem 0}.service-choice-card dt{font-weight:500;color:#64748b}.service-choice-card dd{font-weight:700;margin:0}.fee-summary-card{background:#071f43;color:#fff;border-radius:1rem;padding:1.5rem}.fee-summary-card .grand-total{border-top:1px solid #557092;margin-top:.5rem;padding-top:1rem}.fee-summary-card p{color:#c9d7eb;margin:.75rem 0 0}.document-upload-sections{display:grid;gap:1.5rem;margin-bottom:1.5rem}.document-upload-section{padding:1.25rem;background:#f8fbff;border:1px solid #dbe7f5;border-radius:1rem}.document-section-heading{display:flex;align-items:flex-start;gap:.8rem;margin-bottom:1rem}.document-section-heading h3{color:#15375f;font-size:1.05rem;font-weight:800;margin:0}.document-section-heading p{color:#64748b;font-size:.8rem;margin:.2rem 0 0}.document-section-icon{display:grid;place-items:center;flex:0 0 2.25rem;height:2.25rem;color:#0b5ed7;background:#e5f0ff;border-radius:.7rem}.document-upload-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1rem;list-style:none;padding:0;margin:0}.document-upload-card{display:flex;flex-direction:column;min-width:0;padding:1rem;background:#fff;border:1px solid #dce5f2;border-radius:.9rem;box-shadow:0 .2rem .65rem rgba(12,45,90,.05)}.document-upload-card.is-selected{border-color:#7bc6a7;background:#fbfffd;box-shadow:0 0 0 2px rgba(25,135,84,.08)}.document-upload-name{min-width:0;margin-bottom:.75rem}.document-upload-name strong,.document-upload-name small{display:block;overflow-wrap:anywhere}.document-upload-name strong{color:#17375e;font-size:1rem;line-height:1.5}.document-upload-name small{color:#64748b;font-size:.82rem;line-height:1.45;margin-top:.15rem}.document-upload-badge{align-self:flex-start;margin-bottom:.9rem}.document-upload-input{width:100%;max-width:100%;min-width:0}.document-upload-input::file-selector-button{white-space:nowrap}.document-upload-result{display:flex;align-items:flex-start;justify-content:space-between;gap:.75rem;margin-top:.8rem;padding-top:.8rem;border-top:1px solid #e7edf5}.document-upload-status{min-width:0;line-height:1.4}.document-upload-status strong,.document-upload-status span{display:block}.document-upload-status .selected-document-name{color:#17375e;margin-top:.2rem}.document-upload-status .selected-filename{color:#64748b;overflow-wrap:anywhere}.document-empty-state{grid-column:1/-1;padding:.85rem 1rem;color:#64748b;background:#fff;border:1px dashed #cbd8e8;border-radius:.75rem}.upload-drop-card{display:flex;flex-direction:column;align-items:center;text-align:center;border:2px dashed #8aa8ce;border-radius:1rem;padding:2rem;background:#f8fbff;cursor:pointer}.upload-drop-card i{font-size:2.5rem;color:#0b5ed7}.upload-drop-card input{margin-top:1rem}.review-card{border:1px solid #e1e8f1;border-radius:1rem;padding:1rem;height:100%}.review-card h3{font-size:1rem;color:#0b5ed7}@media(max-width:767px){.request-stepper{grid-template-columns:repeat(2,1fr)}.request-panel{padding:1.25rem!important}.document-upload-section{padding:1rem}.document-upload-grid{grid-template-columns:1fr}.document-upload-result{flex-direction:column}.remove-document-upload{width:100%}}@media(min-width:768px) and (max-width:991.98px){.document-upload-grid{grid-template-columns:1fr}}
</style>@endpush
